const VIEW_TYPE = 'dsh-obsidian-math-view';
const PRESET_NAME = 'obsidian';
const EMBEDDED_PRESET = JSON.parse("{\"preset.yml\":\"name: Obsidian 笔记助手\\ndescription: 面向数学类笔记的最小 agent（试做型 0.1.x）：只保留文件读写与搜索，跨会话分层记忆、笔记工作流、关键想法捕获与备忘录提醒。记忆架构尚未经长期测试，会持续演进。\\norder: 1\\n\",\"agent.cordis.yml\":\"# The `obsidian` agent preset: a deliberately minimal knowledge-base agent.\\n#\\n# Tools kept to the bare essentials the user asked for:\\n#   - tool-fs          read/write/edit files inside the Obsidian vault\\n#   - tool-fs-search   search/glob inside the vault\\n#   - tool-ask-user    ask before capturing key ideas, big edits, etc.\\n# Everything else (shell, web, subagents, workflows, goals, todo, ...) is\\n# deliberately NOT mounted in this preset.\\n#\\n# This file is an AGENT-PLANE composition. The roster mounts it once under a\\n# standing scope; every session naming it joins by scope parentage.\\n\\n# ── identity ────────────────────────────────────────────────────────────────\\n\\n# The deployment persona is shadowed for this agent. We do NOT use\\n# `complete: true` because the obsidian-memory plugin below appends its\\n# per-request memory section during system-prompt assembly, and a complete\\n# persona would discard every other section.\\n- id: persona\\n  name: '@deepseek-ai/dsh-persona'\\n  config:\\n    text: >-\\n      You are the user's long-term Obsidian knowledge-base assistant for\\n      mathematical (and adjacent: statistics, R/LaTeX) notes and\\n      research thinking, powered by the {{model}} model. Your working\\n      directory is the user's Obsidian vault: {{cwd}}.\\n\\n      You are a thinking-and-writing partner, not a general coding agent:\\n      read the user's notes before answering, keep their notation and\\n      theoretical preferences, surface key ideas worth capturing, and keep a\\n      durable memory so future conversations start from where the last one\\n      ended. You may only read and modify files inside the vault through the\\n      provided file tools. For every significant piece of new information\\n      about the user's interests, terminology, or preferences, update the\\n      memory files under `.deepseek/` (see AGENTS.md in the vault root for\\n      the exact protocol). Never invent facts about the user's notes; read\\n      first.\\n\\n- id: agent-instructions\\n  name: '@deepseek-ai/dsh-agent-instructions'\\n  config:\\n    maxBytes: 65536\\n\\n# ── minimal tools ───────────────────────────────────────────────────────────\\n\\n- id: tool-fs\\n  name: '@deepseek-ai/dsh-tool-fs'\\n\\n- id: tool-fs-search\\n  name: '@deepseek-ai/dsh-tool-fs-search'\\n  config:\\n    sampleOverCapGlobResults: false\\n\\n# Asking the user is part of the key-idea capture contract: propose first,\\n# write to the memo only after consent (or an explicit standing consent).\\n- id: tool-ask-user\\n  name: '@deepseek-ai/dsh-tool-ask-user'\\n\\n# ── cross-session memory injection ──────────────────────────────────────────\\n\\n# Local plugin: reads the vault's `.deepseek/memory/*` and `.deepseek/inbox/*`\\n# plus a cached index distilled from this machine's past dsh sessions, and\\n# appends one bounded memory section to every system prompt of this agent.\\n- id: obsidian-memory\\n  name: ./obsidian-memory.mjs\\n  config:\\n    # 留空 = 路径无关：vault 自动取会话 cwd，sessions 自动取 $DSH_HOME/sessions。\\n    # 也可用 DSH_OBSIDIAN_VAULT / DSH_SESSIONS_ROOT 环境变量覆盖。\\n    vaultRoot: ''\\n    sessionsRoot: ''\\n    maxHistoryEntries: 40\\n    maxHistoryChars: 8000\\n    cacheTtlMs: 0\\n\",\"obsidian-memory.mjs\":\"/**\\n * obsidian-memory — cross-session memory injection for the `obsidian` dsh\\n * agent preset.\\n *\\n * What it does, on every system-prompt assembly for this agent:\\n *   1. Reads the vault's durable memory files (`.deepseek/memory/*` and a\\n *      one-line digest of `.deepseek/inbox/*`). These are maintained BY THE\\n *      MODEL through the ordinary file tools, per the vault's AGENTS.md.\\n *   2. Distills a small dialogue index from this machine's past dsh session\\n *      logs (session.jsonl.zstd files under `$DSH_HOME/sessions/`) — recent user\\n *      questions plus short assistant conclusions — so a brand-new session\\n *      no longer starts from zero.\\n *   3. Appends one bounded \\\"obsidian:memory\\\" section to the assembled system\\n *      prompt.\\n *\\n * It never calls the model and never mutates any user note. The only file it\\n * writes is its own cache at `<vault>/.deepseek/cache/dialogue-index.json`.\\n *\\n * Session logs are concatenated Zstandard frames (one JSONL batch per frame).\\n * Node >= 22.5 provides zstd through node:zlib; on older runtimes the\\n * dialogue index is skipped and only vault memory files are injected.\\n */\\n\\nimport * as zlib from \\\"node:zlib\\\";\\nimport {\\n  existsSync,\\n  mkdirSync,\\n  readdirSync,\\n  readFileSync,\\n  renameSync,\\n  statSync,\\n  writeFileSync\\n} from \\\"node:fs\\\";\\nimport { dirname, isAbsolute, join, resolve } from \\\"node:path\\\";\\nimport { homedir } from \\\"node:os\\\";\\n\\nexport const name = \\\"obsidian-memory\\\";\\nexport const inject = [\\\"systemPrompt\\\"];\\n\\nconst ZSTD_MAGIC = 4247762216; // little-endian 28 B5 2F FD\\nconst MEMORY_DIR = \\\".deepseek\\\";\\nconst CACHE_DIR = join(MEMORY_DIR, \\\"cache\\\");\\nconst CACHE_FILE = join(CACHE_DIR, \\\"dialogue-index.json\\\");\\nconst LOG_SUFFIX = \\\".jsonl.zstd\\\";\\nconst MAX_LOG_FILES = 20;\\n// Layered injection budget (arXiv:2606.24775): the prompt carries navigation\\n// layers only; raw evidence lives on disk and is reached via grep/read.\\nconst MAX_PROFILE_CHARS = 4000;\\nconst MAX_TOPIC_INDEX_CHARS = 4000;\\nconst MAX_RECORD_INDEX_CHARS = 2000;\\nconst MAX_TEMPLATE_INDEX_CHARS = 1500;\\nconst MAX_EPISODE_INDEX_CHARS = 2500;\\nconst MAX_INBOX_CHARS = 2200;\\nconst MAX_DIALOGUE_PAIRS = 6;\\nconst MAX_DIALOGUE_CHARS = 3000;\\nconst DEFAULT_MAX_HISTORY_ENTRIES = 40;\\nconst DEFAULT_MAX_HISTORY_CHARS = 6000;\\n\\n// ── zstd session-log decoding ───────────────────────────────────────────────\\n\\n/** Locate every complete Zstandard frame in a concatenated-frame file. */\\nexport function scanZstdFrames(buffer) {\\n  const frames = [];\\n  let offset = 0;\\n  while (offset < buffer.length) {\\n    const start = offset;\\n    if (buffer.length - offset < 4) return frames;\\n    if (buffer.readUInt32LE(offset) !== ZSTD_MAGIC) {\\n      throw new Error(`obsidian-memory: bad zstd frame magic at byte ${offset}`);\\n    }\\n    offset += 4;\\n    if (offset === buffer.length) return frames; // torn header after magic\\n    const descriptor = buffer.readUInt8(offset);\\n    offset += 1;\\n    if ((descriptor & 24) !== 0) throw new Error(`obsidian-memory: reserved zstd frame-header bit at byte ${offset - 1}`);\\n    const contentSizeFlag = descriptor >>> 6;\\n    const singleSegment = (descriptor & 32) !== 0;\\n    const hasChecksum = (descriptor & 4) !== 0;\\n    const dictionaryFlag = descriptor & 3;\\n    const dictionaryBytes = dictionaryFlag === 3 ? 4 : dictionaryFlag;\\n    const contentSizeBytes = contentSizeFlag === 0 ? (singleSegment ? 1 : 0) : (1 << contentSizeFlag);\\n    const remainingHeaderBytes = (singleSegment ? 0 : 1) + dictionaryBytes + contentSizeBytes;\\n    if (buffer.length - offset < remainingHeaderBytes) return frames; // torn header\\n    offset += remainingHeaderBytes;\\n    for (;;) {\\n      if (buffer.length - offset < 3) return frames; // torn block header\\n      const blockHeader = buffer.readUIntLE(offset, 3);\\n      offset += 3;\\n      const lastBlock = (blockHeader & 1) !== 0;\\n      const blockType = (blockHeader >>> 1) & 3;\\n      const blockSize = blockHeader >>> 3;\\n      if (blockType === 3) throw new Error(`obsidian-memory: reserved zstd block type at byte ${offset - 3}`);\\n      const payloadBytes = blockType === 1 ? 1 : blockSize;\\n      if (buffer.length - offset < payloadBytes) return frames; // torn payload\\n      offset += payloadBytes;\\n      if (lastBlock) break;\\n    }\\n    if (hasChecksum) {\\n      if (buffer.length - offset < 4) return frames; // torn checksum\\n      offset += 4;\\n    }\\n    frames.push([start, offset]);\\n  }\\n  return frames;\\n}\\n\\n/** Decode one full session artifact into its JSONL event objects. */\\nexport function decodeZstdSessionLog(buffer) {\\n  const events = [];\\n  if (typeof zlib.zstdDecompressSync !== \\\"function\\\") return events;\\n  for (const [start, end] of scanZstdFrames(buffer)) {\\n    let text;\\n    try {\\n      text = zlib.zstdDecompressSync(buffer.subarray(start, end)).toString(\\\"utf8\\\");\\n    } catch {\\n      continue; // tolerate a torn/foreign final frame; keep committed frames\\n    }\\n    for (const line of text.split(\\\"\\\\n\\\")) {\\n      if (line.trim() === \\\"\\\") continue;\\n      try {\\n        events.push(JSON.parse(line));\\n      } catch {\\n        // Ignore malformed individual lines; the durable log is append-only.\\n      }\\n    }\\n  }\\n  return events;\\n}\\n\\n// ── text extraction ─────────────────────────────────────────────────────────\\n\\nfunction contentText(content) {\\n  if (!Array.isArray(content)) return \\\"\\\";\\n  return content\\n    .filter((block) => block?.type === \\\"text\\\" && typeof block.text === \\\"string\\\")\\n    .map((block) => block.text)\\n    .join(\\\"\\\\n\\\")\\n    .trim();\\n}\\n\\nfunction clip(text, maxChars) {\\n  if (text.length <= maxChars) return text;\\n  return `${text.slice(0, maxChars).replace(/\\\\s+\\\\S*$/, \\\"\\\")} …`;\\n}\\n\\n/**\\n * Walk one decoded session into a compact entry:\\n * `{ id, title, cwd, messages: [{ role, text, time }] }`.\\n * Plugin-injected user messages (runtime-context snapshots, approval notices)\\n * are skipped; only real human turns (`source.kind === \\\"user\\\"`) count.\\n */\\nexport function distillSession(events) {\\n  const entry = { id: undefined, title: undefined, cwd: undefined, messages: [] };\\n  for (const event of events) {\\n    if (event?.type === \\\"session\\\" && typeof event.id === \\\"string\\\") {\\n      entry.id = event.id;\\n      entry.cwd = typeof event.cwd === \\\"string\\\" ? event.cwd : entry.cwd;\\n    } else if (event?.type === \\\"session/title\\\" && typeof event.data?.title === \\\"string\\\") {\\n      entry.title = event.data.title;\\n    } else if (event?.type === \\\"user/message\\\" && event.data?.source?.kind === \\\"user\\\") {\\n      const text = contentText(event.data.content);\\n      if (text !== \\\"\\\") {\\n        entry.messages.push({ role: \\\"user\\\", text: clip(text, 500), time: event.time ?? 0 });\\n      }\\n    } else if (event?.type === \\\"assistant/message\\\") {\\n      const text = contentText(event.data?.message?.content);\\n      if (text !== \\\"\\\") {\\n        entry.messages.push({ role: \\\"assistant\\\", text: clip(text, 320), time: event.time ?? 0 });\\n      }\\n    }\\n  }\\n  return entry;\\n}\\n\\n// ── session root walking ────────────────────────────────────────────────────\\n\\n/** Recursively list session artifacts, newest first, bounded by `maxFiles`. */\\nexport function findSessionLogs(sessionsRoot, maxFiles = MAX_LOG_FILES) {\\n  const found = [];\\n  const walk = (dir) => {\\n    let children;\\n    try {\\n      children = readdirSync(dir, { withFileTypes: true });\\n    } catch {\\n      return;\\n    }\\n    for (const child of children) {\\n      const path = join(dir, child.name);\\n      if (child.isDirectory()) walk(path);\\n      else if (child.isFile() && child.name.endsWith(LOG_SUFFIX)) {\\n        try {\\n          const stats = statSync(path);\\n          found.push({ path, mtimeMs: stats.mtimeMs, size: stats.size });\\n        } catch {\\n          // Gone while walking; skip.\\n        }\\n      }\\n    }\\n  };\\n  walk(sessionsRoot);\\n  found.sort((a, b) => b.mtimeMs - a.mtimeMs);\\n  return found.slice(0, maxFiles);\\n}\\n\\n/**\\n * Build the dialogue index used by the memory section: recent user turns and\\n * the assistant texts that followed, flattened in time order.\\n */\\nexport function buildDialogueIndex(sessionsRoot, maxEntries, maxChars, maxFiles = MAX_LOG_FILES) {\\n  const sources = [];\\n  const sessions = [];\\n  for (const log of findSessionLogs(sessionsRoot, maxFiles)) {\\n    let buffer;\\n    try {\\n      buffer = readFileSync(log.path);\\n    } catch {\\n      continue;\\n    }\\n    let events = [];\\n    try {\\n      events = decodeZstdSessionLog(buffer);\\n    } catch {\\n      continue;\\n    }\\n    const entry = distillSession(events);\\n    if (entry.id !== undefined && entry.messages.length > 0) {\\n      sources.push({ path: log.path, mtimeMs: log.mtimeMs, size: log.size });\\n      sessions.push(entry);\\n    }\\n  }\\n\\n  // Turn each real user message into a Q/A pair: the question plus the first\\n  // assistant text that followed it in the same session. Newest pairs first.\\n  const threads = [];\\n  for (const session of sessions) {\\n    const messages = [...session.messages].sort((a, b) => a.time - b.time);\\n    for (let index = 0; index < messages.length; index += 1) {\\n      const message = messages[index];\\n      if (message.role !== \\\"user\\\") continue;\\n      const answer = messages.slice(index + 1).find((candidate) => candidate.role === \\\"assistant\\\");\\n      threads.push({\\n        sessionId: session.id,\\n        title: session.title,\\n        cwd: session.cwd,\\n        time: message.time,\\n        user: message,\\n        assistant: answer\\n      });\\n    }\\n  }\\n  threads.sort((a, b) => a.time - b.time);\\n\\n  const entries = [];\\n  let used = 0;\\n  for (const thread of threads.slice(-maxEntries).reverse()) {\\n    const question = thread.user.text;\\n    const answer = thread.assistant?.text ?? \\\"\\\";\\n    const questionBudget = Math.min(question.length, 400);\\n    const answerBudget = Math.min(answer.length, 240);\\n    if (used + questionBudget + answerBudget > maxChars) break;\\n    entries.push({\\n      sessionId: thread.sessionId,\\n      title: typeof thread.title === \\\"string\\\" ? thread.title : undefined,\\n      role: \\\"user\\\",\\n      text: question.slice(0, questionBudget),\\n      time: thread.time\\n    });\\n    used += questionBudget;\\n    if (answerBudget > 0) {\\n      entries.push({\\n        sessionId: thread.sessionId,\\n        title: typeof thread.title === \\\"string\\\" ? thread.title : undefined,\\n        role: \\\"assistant\\\",\\n        text: answer.slice(0, answerBudget),\\n        time: thread.time\\n      });\\n      used += answerBudget;\\n    }\\n  }\\n  return {\\n    generatedAt: Date.now(),\\n    sources,\\n    entries\\n  };\\n}\\n\\n// ── durable vault memory files ──────────────────────────────────────────────\\n\\nfunction readMemoryFile(root, relativePath, maxChars) {\\n  const path = join(root, relativePath);\\n  if (!existsSync(path)) return \\\"\\\";\\n  try {\\n    return clip(readFileSync(path, \\\"utf8\\\").trim(), maxChars);\\n  } catch {\\n    return \\\"\\\";\\n  }\\n}\\n\\n/** Files that are memo-library scaffolding, not memos. */\\nconst MEMO_SCAFFOLD = new Set([\\\"index.md\\\", \\\"_README.md\\\"]);\\nconst MEMO_STATES = new Set([\\\"inbox\\\", \\\"polishing\\\", \\\"done\\\"]);\\nconst MEMO_STALE_INBOX_DAYS = 7;\\nconst MEMO_STALE_POLISHING_DAYS = 3;\\n\\n/** Parse the YAML-ish frontmatter of one memo plus its first `#` title. */\\nexport function parseMemoFrontmatter(text) {\\n  const meta = {};\\n  const match = /^---\\\\r?\\\\n([\\\\s\\\\S]*?)\\\\r?\\\\n---/.exec(text ?? \\\"\\\");\\n  if (match !== null) {\\n    for (const line of match[1].split(/\\\\r?\\\\n/)) {\\n      const pair = /^([A-Za-z_][\\\\w-]*):\\\\s*(.*)$/.exec(line.trim());\\n      if (pair !== null) meta[pair[1]] = pair[2].trim().replace(/^[\\\"']|[\\\"']$/g, \\\"\\\");\\n    }\\n  }\\n  const title = /^#\\\\s+(.+)$/m.exec(text ?? \\\"\\\")?.[1]?.trim();\\n  if (title !== undefined && meta.title === undefined) meta.title = title;\\n  return meta;\\n}\\n\\nfunction parseLocalDay(value) {\\n  const match = /^(\\\\d{4})-(\\\\d{2})-(\\\\d{2})/.exec(value ?? \\\"\\\");\\n  if (match === null) return null;\\n  return new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]));\\n}\\n\\nfunction daysSinceLocal(value) {\\n  const day = parseLocalDay(value);\\n  if (day === null) return null;\\n  return Math.floor((Date.now() - day.getTime()) / 86400000);\\n}\\n\\nfunction localDateString() {\\n  const now = new Date();\\n  return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, \\\"0\\\")}-${String(now.getDate()).padStart(2, \\\"0\\\")}`;\\n}\\n\\n/**\\n * Memo status digest: group live memos by lifecycle state and surface the\\n * top stale candidates (inbox >= 7 days, polishing >= 3 days, and not yet\\n * reminded today) for the agent's proactive review prompts.\\n */\\nexport function memoDigest(root, maxChars) {\\n  const memoDir = join(root, MEMORY_DIR, \\\"inbox\\\");\\n  if (!existsSync(memoDir)) return \\\"\\\";\\n  let files = [];\\n  try {\\n    files = readdirSync(memoDir, { withFileTypes: true })\\n      .filter((entry) => entry.isFile() && entry.name.endsWith(\\\".md\\\") && !MEMO_SCAFFOLD.has(entry.name) && !entry.name.startsWith(\\\"_\\\"))\\n      .map((entry) => entry.name);\\n  } catch {\\n    return \\\"\\\";\\n  }\\n  if (files.length === 0) return \\\"\\\";\\n\\n  const groups = { inbox: [], polishing: [], done: [] };\\n  const today = localDateString();\\n  for (const file of files) {\\n    let meta;\\n    try {\\n      meta = parseMemoFrontmatter(readFileSync(join(memoDir, file), \\\"utf8\\\"));\\n    } catch {\\n      continue;\\n    }\\n    const slug = file.replace(/\\\\.md$/, \\\"\\\");\\n    const status = MEMO_STATES.has(meta.status) ? meta.status : \\\"inbox\\\";\\n    const updated = meta.updated ?? \\\"\\\";\\n    const days = daysSinceLocal(updated);\\n    const item = {\\n      slug,\\n      title: meta.title || slug,\\n      topic: meta.topic || \\\"未归类\\\",\\n      updated,\\n      days,\\n      stale: days !== null && days >= (status === \\\"polishing\\\" ? MEMO_STALE_POLISHING_DAYS : MEMO_STALE_INBOX_DAYS),\\n      alreadyReminded: meta.last_reminded === today\\n    };\\n    groups[status].push(item);\\n  }\\n\\n  const stateLabel = { inbox: \\\"待打磨\\\", polishing: \\\"打磨中\\\", done: \\\"已完成\\\" };\\n  const lines = [];\\n  for (const status of [\\\"inbox\\\", \\\"polishing\\\", \\\"done\\\"]) {\\n    const members = groups[status].sort((a, b) => (b.days ?? -1) - (a.days ?? -1));\\n    if (members.length === 0) continue;\\n    lines.push(`- ${stateLabel[status]}（${status}）· ${members.length} 条`);\\n    for (const memo of members) {\\n      const parts = [`[[${memo.slug}|${memo.title}]]`, `主题:${memo.topic}`];\\n      if (memo.updated !== \\\"\\\") parts.push(`updated:${memo.updated}`);\\n      lines.push(`  - ${parts.join(\\\" · \\\")}`);\\n    }\\n  }\\n\\n  const candidates = [...groups.inbox, ...groups.polishing]\\n    .filter((memo) => memo.stale && !memo.alreadyReminded)\\n    .sort((a, b) => (b.days ?? -1) - (a.days ?? -1))\\n    .slice(0, 3);\\n  if (candidates.length > 0) {\\n    lines.push(\\\"- 🔔 提醒候选（久未更新）\\\");\\n    for (const memo of candidates) {\\n      lines.push(`  - [[${memo.slug}|${memo.title}]]：${memo.days} 天未更新，可在相关讨论时建议打磨`);\\n    }\\n  }\\n\\n  return clip(lines.join(\\\"\\\\n\\\"), maxChars);\\n}\\n\\n/** Episode timeline: keep the newest lines (list items only) within budget. */\\nfunction episodeIndexDigest(root, maxChars) {\\n  const path = join(root, MEMORY_DIR, \\\"memory\\\", \\\"episodes\\\", \\\"index.md\\\");\\n  if (!existsSync(path)) return \\\"\\\";\\n  try {\\n    const text = readFileSync(path, \\\"utf8\\\").trim();\\n    if (text === \\\"\\\") return \\\"\\\";\\n    const items = text.split(\\\"\\\\n\\\").filter((line) => line.trim().startsWith(\\\"-\\\"));\\n    if (items.length === 0) return clip(text, maxChars);\\n    // Index lines are append-only, newest at the bottom: keep the tail.\\n    const kept = [];\\n    let used = 0;\\n    for (const line of items.reverse()) {\\n      const clean = clip(line.trim(), maxChars);\\n      if (used + clean.length > maxChars) break;\\n      kept.push(clean);\\n      used += clean.length + 1;\\n    }\\n    return kept.reverse().join(\\\"\\\\n\\\");\\n  } catch {\\n    return \\\"\\\";\\n  }\\n}\\n\\n/** Typed atomic-record digest: keep the index's list lines within budget. */\\nfunction recordIndexDigest(root, maxChars) {\\n  const path = join(root, MEMORY_DIR, \\\"memory\\\", \\\"records\\\", \\\"index.md\\\");\\n  if (!existsSync(path)) return \\\"\\\";\\n  try {\\n    const text = readFileSync(path, \\\"utf8\\\").trim();\\n    if (text === \\\"\\\") return \\\"\\\";\\n    const items = text.split(\\\"\\\\n\\\").filter((line) => line.trim().startsWith(\\\"-\\\"));\\n    if (items.length === 0) return clip(text, maxChars);\\n    return clip(items.map((line) => line.trim()).join(\\\"\\\\n\\\"), maxChars);\\n  } catch {\\n    return \\\"\\\";\\n  }\\n}\\n\\n/** Problem-template index digest (personal template-theorems graph). */\\nfunction templateIndexDigest(root, maxChars) {\\n  const path = join(root, MEMORY_DIR, \\\"memory\\\", \\\"templates\\\", \\\"index.md\\\");\\n  if (!existsSync(path)) return \\\"\\\";\\n  try {\\n    const text = readFileSync(path, \\\"utf8\\\").trim();\\n    if (text === \\\"\\\") return \\\"\\\";\\n    const items = text.split(\\\"\\\\n\\\").filter((line) => line.trim().startsWith(\\\"-\\\"));\\n    if (items.length === 0) return clip(text, maxChars);\\n    return clip(items.map((line) => line.trim()).join(\\\"\\\\n\\\"), maxChars);\\n  } catch {\\n    return \\\"\\\";\\n  }\\n}\\n\\n// ── the section composer ────────────────────────────────────────────────────\\n/**\\n * Render the layered memory section for one agent.\\n *\\n * Layout follows the paper's routing philosophy: stable semantics + topic\\n * navigation + inbox/episode timelines are always injected (coarse layers);\\n * raw episodic evidence is left on disk for grep/read (fine layer). Past\\n * dialogue cues are capped at a few Q/A pairs to keep the prompt bounded.\\n * `context.agent` supplies the current session id so the live conversation is\\n * never duplicated into the \\\"past dialogue\\\" index.\\n */\\nexport function buildMemorySection({ vaultRoot, sessionsRoot, maxHistoryEntries, maxHistoryChars, cacheTtlMs }, currentSessionId, dialogueIndex) {\\n  const profile = readMemoryFile(vaultRoot, join(MEMORY_DIR, \\\"memory\\\", \\\"profile.md\\\"), MAX_PROFILE_CHARS);\\n  const topics = readMemoryFile(vaultRoot, join(MEMORY_DIR, \\\"memory\\\", \\\"topics\\\", \\\"index.md\\\"), MAX_TOPIC_INDEX_CHARS);\\n  const records = recordIndexDigest(vaultRoot, MAX_RECORD_INDEX_CHARS);\\n  const templates = templateIndexDigest(vaultRoot, MAX_TEMPLATE_INDEX_CHARS);\\n  const episodes = episodeIndexDigest(vaultRoot, MAX_EPISODE_INDEX_CHARS);\\n  const memos = memoDigest(vaultRoot, MAX_INBOX_CHARS);\\n\\n  const lines = [\\n    \\\"## 分层长期记忆（由 obsidian-memory 自动注入；导航层在此，证据层在磁盘）\\\",\\n    \\\"\\\",\\n    \\\"记忆按 arXiv:2606.24775 与 arXiv:2607.05794 的原则组织为五层：profile=语义层，topics=导航层，\\\" +\\n    \\\"records=类型化原子记录层，episodes=原始证据层，inbox=想法层。以下内容用于“知道去哪找”，不要当作完整证据。\\\" +\\n    \\\"回答细节问题时必须按路由规则读文件：\\\",\\n    \\\"- 精确事实 / 用户原话 / 日期数字 → 先 grep `.deepseek/memory/episodes/` 再读命中文件；\\\",\\n    \\\"- 类型化原子事实（fact/event/instruction/preference）→ 先看 `.deepseek/memory/records/index.md`，再 grep/读具体记录，记录里的 source 可回原始证据；\\\",\\n    \\\"- 主题来龙去脉 → 先读 `.deepseek/memory/topics/index.md` 定位，再读 `topics/<slug>.md` 或相关笔记；\\\",\\n    \\\"- “当前最新状态” → 比较 frontmatter `updated` 或最新 episode 时间戳；\\\",\\n    \\\"- 检索不到就明说没有，不要编造。\\\"\\n  ];\\n\\n  if (profile !== \\\"\\\") {\\n    lines.push(\\\"\\\", \\\"### 用户画像与稳定偏好（.deepseek/memory/profile.md）\\\", \\\"\\\", profile);\\n  } else {\\n    lines.push(\\\"\\\", \\\"### 用户画像与稳定偏好\\\", \\\"\\\", \\\"（尚未建立。按 AGENTS.md 在首次对话后创建 .deepseek/memory/profile.md。）\\\");\\n  }\\n\\n  if (topics !== \\\"\\\") {\\n    lines.push(\\\"\\\", \\\"### 研究主题索引（.deepseek/memory/topics/index.md）\\\", \\\"\\\", topics);\\n  } else {\\n    lines.push(\\\"\\\", \\\"### 研究主题索引\\\", \\\"\\\", \\\"（尚未建立。按 AGENTS.md 在 .deepseek/memory/topics/index.md 维护主题条目。）\\\");\\n  }\\n\\n  if (records !== \\\"\\\") {\\n    lines.push(\\\"\\\", \\\"### 记忆记录摘要（.deepseek/memory/records/index.md，类型化原子事实）\\\", \\\"\\\", records);\\n  } else {\\n    lines.push(\\\"\\\", \\\"### 记忆记录摘要\\\", \\\"\\\", \\\"（尚无原子记录。每轮收尾时按 AGENTS.md 三写协议，从 episode 提炼 fact/event/instruction/preference 记录。）\\\");\\n  }\\n\\n  if (templates !== \\\"\\\") {\\n    lines.push(\\\"\\\", \\\"### 问题模板索引（.deepseek/memory/templates/index.md，题型/解法 ↔ 定理关联）\\\", \\\"\\\", templates,\\n      \\\"\\\", \\\"遇到新问题先做“问题蒸馏”（抽象成模板表达）再查这里；命中则读模板卡与关联定理并去重聚合。\\\");\\n  }\\n\\n  if (episodes !== \\\"\\\") {\\n    lines.push(\\\"\\\", \\\"### 近期事件时间线（.deepseek/memory/episodes/index.md，最新在前）\\\", \\\"\\\", episodes);\\n  } else {\\n    lines.push(\\\"\\\", \\\"### 近期事件时间线\\\", \\\"\\\", \\\"（尚无事件记录。每轮对话收尾时按 AGENTS.md 双写 episodes。）\\\");\\n  }\\n\\n  if (memos !== \\\"\\\") {\\n    lines.push(\\\"\\\", \\\"### 备忘录状态与提醒候选（.deepseek/inbox/，AI 维护）\\\", \\\"\\\", memos,\\n      \\\"\\\", \\\"当本轮讨论与上述某条 memo 明显相关（新证据、新反例、可推进其“待打磨”清单）时，\\\",\\n      \\\"按 AGENTS.md 第 5 节在回复末尾给出“🔔 备忘录提醒”并用 ask_user_question 询问是否现在打磨；\\\",\\n      \\\"每条 memo 每天最多提醒一次，提醒后把它的 last_reminded 更新为当天日期。\\\");\\n  } else {\\n    lines.push(\\\"\\\", \\\"### 备忘录状态与提醒候选\\\", \\\"\\\", \\\"（.deepseek/inbox/ 尚无 memo。捕捉到新想法并经用户同意后，按 AGENTS.md 第 5 节创建。）\\\");\\n  }\\n\\n  // Past-dialogue cues: newest first, at most MAX_DIALOGUE_PAIRS Q/A pairs.\\n  const recent = (dialogueIndex?.entries ?? []).filter((entry) => entry.sessionId !== currentSessionId);\\n  if (recent.length > 0) {\\n    const cues = [];\\n    let pairs = 0;\\n    let used = 0;\\n    for (const entry of recent) {\\n      const text = entry.text.replace(/\\\\n+/g, \\\" \\\");\\n      const budget = entry.role === \\\"user\\\" ? Math.min(text.length, 320) : Math.min(text.length, 220);\\n      if (used + budget > MAX_DIALOGUE_CHARS) break;\\n      if (entry.role === \\\"user\\\") {\\n        if (pairs >= MAX_DIALOGUE_PAIRS) break;\\n        pairs += 1;\\n      } else if (pairs === 0) {\\n        continue; // never start with an orphaned assistant cue\\n      }\\n      cues.push({ ...entry, text: text.slice(0, budget) });\\n      used += budget;\\n    }\\n    if (cues.length > 0) {\\n      lines.push(\\\"\\\", \\\"### 近期跨会话问答线索（最多 6 组，细节请 grep episodes）\\\", \\\"\\\");\\n      let lastSessionId;\\n      for (const entry of cues) {\\n        if (entry.sessionId !== lastSessionId) {\\n          lines.push(`- 会话${entry.title !== undefined ? `《${entry.title}》` : \\\"\\\"}（${new Date(entry.time).toLocaleString(\\\"zh-CN\\\", { hour12: false })}）`);\\n          lastSessionId = entry.sessionId;\\n        }\\n        const label = entry.role === \\\"user\\\" ? \\\"问\\\" : \\\"答\\\";\\n        lines.push(`  - ${label}: ${entry.text}`);\\n      }\\n    }\\n  }\\n\\n  return lines.join(\\\"\\\\n\\\");\\n}\\n\\n// ── engine with per-process caching ─────────────────────────────────────────\\n\\nfunction defaultSessionsRoot() {\\n  const home = process.env.DSH_HOME ?? join(homedir(), \\\".dsh\\\");\\n  return join(home, \\\"sessions\\\");\\n}\\n\\nfunction normalizeConfig(config) {\\n  const vaultRaw = (process.env.DSH_OBSIDIAN_VAULT ?? config.vaultRoot ?? \\\"\\\").trim();\\n  // Empty vaultRoot means \\\"the agent's session cwd\\\" — resolved per agent so the\\n  // same preset is portable across machines and vaults.\\n  const vaultRoot = vaultRaw === \\\"\\\" ? \\\"\\\" : resolve(vaultRaw);\\n  const sessionsRaw = (process.env.DSH_SESSIONS_ROOT ?? config.sessionsRoot ?? \\\"\\\").trim();\\n  const sessionsRoot = resolve(sessionsRaw === \\\"\\\" ? defaultSessionsRoot() : sessionsRaw);\\n  const maxHistoryEntries = Number.isInteger(config.maxHistoryEntries) && config.maxHistoryEntries > 0\\n    ? config.maxHistoryEntries\\n    : DEFAULT_MAX_HISTORY_ENTRIES;\\n  const maxHistoryChars = Number.isInteger(config.maxHistoryChars) && config.maxHistoryChars > 0\\n    ? config.maxHistoryChars\\n    : DEFAULT_MAX_HISTORY_CHARS;\\n  const cacheTtlMs = Number.isFinite(config.cacheTtlMs) && config.cacheTtlMs >= 0 ? config.cacheTtlMs : 0;\\n  if (!isAbsolute(sessionsRoot)) throw new TypeError(\\\"obsidian-memory: sessionsRoot must be an absolute path\\\");\\n  return { vaultRoot, sessionsRoot, maxHistoryEntries, maxHistoryChars, cacheTtlMs };\\n}\\n\\nfunction resolveVaultRoot(config, agent) {\\n  if (config.vaultRoot !== \\\"\\\") return config.vaultRoot;\\n  const cwd = agent?.session?.header?.cwd ?? agent?.session?.cwd;\\n  if (typeof cwd === \\\"string\\\" && cwd !== \\\"\\\" && isAbsolute(cwd)) return cwd;\\n  return \\\"\\\";\\n}\\n\\nfunction fingerprint(logs) {\\n  return logs.map((log) => `${log.path}|${log.mtimeMs}|${log.size}`).join(\\\"\\\\n\\\");\\n}\\n\\nfunction readCachedIndex(cachePath) {\\n  try {\\n    const cached = JSON.parse(readFileSync(cachePath, \\\"utf8\\\"));\\n    if (Array.isArray(cached?.entries) && Array.isArray(cached?.sources)) return cached;\\n  } catch {\\n    // Cache missing/corrupt: rebuild.\\n  }\\n  return undefined;\\n}\\n\\nfunction writeCachedIndex(cachePath, index) {\\n  try {\\n    mkdirSync(dirname(cachePath), { recursive: true });\\n    const staging = `${cachePath}.tmp-${process.pid}`;\\n    writeFileSync(staging, JSON.stringify(index));\\n    renameSync(staging, cachePath);\\n  } catch {\\n    // A cache write failure must never break the prompt.\\n  }\\n}\\n\\nclass MemoryEngine {\\n  #config;\\n  #cachedIndex;\\n  #fingerprint = \\\"\\\";\\n  #builtAt = 0;\\n\\n  constructor(config) {\\n    this.#config = normalizeConfig(config);\\n  }\\n\\n  cachePathFor(vaultRoot) {\\n    return join(vaultRoot, CACHE_FILE);\\n  }\\n\\n  /** Return the current dialogue index, rebuilding it only when sources changed. */\\n  getDialogueIndex(vaultRoot, force = false) {\\n    const config = this.#config;\\n    const logs = findSessionLogs(config.sessionsRoot, MAX_LOG_FILES);\\n    const current = fingerprint(logs);\\n    const stale = force ||\\n      this.#cachedIndex === undefined ||\\n      current !== this.#fingerprint ||\\n      (config.cacheTtlMs > 0 && Date.now() - this.#builtAt > config.cacheTtlMs);\\n    if (!stale) return this.#cachedIndex;\\n\\n    // Reuse the on-disk cache when its source fingerprint still matches.\\n    if (this.#cachedIndex === undefined) {\\n      const disk = readCachedIndex(this.cachePathFor(vaultRoot));\\n      if (disk !== undefined && fingerprint(disk.sources ?? []) === current) {\\n        this.#cachedIndex = disk;\\n        this.#fingerprint = current;\\n        this.#builtAt = disk.generatedAt ?? Date.now();\\n        return this.#cachedIndex;\\n      }\\n    }\\n\\n    const index = buildDialogueIndex(\\n      config.sessionsRoot,\\n      config.maxHistoryEntries,\\n      config.maxHistoryChars,\\n      MAX_LOG_FILES\\n    );\\n    this.#cachedIndex = index;\\n    this.#fingerprint = current;\\n    this.#builtAt = Date.now();\\n    writeCachedIndex(this.cachePathFor(vaultRoot), index);\\n    return index;\\n  }\\n\\n  async sectionForAgent(agent) {\\n    const config = this.#config;\\n    try {\\n      const vaultRoot = resolveVaultRoot(config, agent);\\n      if (vaultRoot === \\\"\\\") {\\n        return \\\"## 长期记忆（obsidian-memory 未配置）\\\\n\\\\n\\\" +\\n          \\\"当前会话没有可用的 vault 工作目录；设置 DSH_OBSIDIAN_VAULT 或在 preset 配置 vaultRoot。\\\";\\n      }\\n      const currentSessionId = agent?.session?.id;\\n      const dialogueIndex = this.getDialogueIndex(vaultRoot);\\n      return buildMemorySection({ ...config, vaultRoot }, currentSessionId, dialogueIndex);\\n    } catch (error) {\\n      return `## 长期记忆（obsidian-memory 暂不可用）\\\\n\\\\n${String(error)}`;\\n    }\\n  }\\n}\\n\\n// ── Cordis plugin entry ─────────────────────────────────────────────────────\\n\\nexport function apply(ctx, config) {\\n  const engine = new MemoryEngine(config);\\n  ctx.on(\\\"system-prompt/assemble\\\", async (assembly, context, next) => {\\n    const assembled = await next();\\n    if (context?.agent === undefined) return assembled;\\n    const text = await engine.sectionForAgent(context.agent);\\n    if (text === \\\"\\\") return assembled;\\n    return {\\n      ...assembled,\\n      sections: [...assembled.sections, { name: \\\"obsidian:memory\\\", text }]\\n    };\\n  });\\n}\\n\",\"profile-package.json\":\"{\\n  \\\"name\\\": \\\"dsh-profile-obsidian\\\",\\n  \\\"private\\\": true,\\n  \\\"dependencies\\\": {},\\n  \\\"dsh\\\": {\\n    \\\"profile\\\": {\\n      \\\"bundles\\\": [\\n        \\\"@deepseek-ai/dsh-base\\\",\\n        \\\"@deepseek-ai/dsh-web-app\\\"\\n      ]\\n    }\\n  }\\n}\\n\",\"profile-cordis.yml\":\"# dsh profile root — an empty entry list. The tree is composed as patches:\\n# each bundle in package.json's dsh.profile.bundles, then cordis.patch.yml, then any\\n# --patch overlays. Edit cordis.patch.yml, not this file.\\n[]\\n\",\"profile-cordis.patch.yml\":\"# Obsidian mode patch layer, applied after dsh-base + dsh-web-app.\\n#\\n# A patch replaces the targeted row's whole config, so each row below\\n# restates the keys it owns.\\n\\n# The agent this profile defaults to: only file read/write/search + ask_user,\\n# plus the cross-session memory plugin.\\n- id: agent-presets\\n  config:\\n    default: obsidian\\n    includeUserRoot: true\\n\\n# Confine every model write to the Obsidian vault (reads stay unrestricted,\\n# matching the harness read model). Set DSH_OBSIDIAN_VAULT to override the\\n# machine-local default without editing this file.\\n- id: sandbox-policy\\n  config:\\n    mode: workspace-write\\n    workspaceRoot: !!js process.env.DSH_OBSIDIAN_VAULT ?? process.cwd()\\n\\n# Default relative-path root for the filesystem backend.\\n- id: fs-sandbox\\n  config:\\n    cwd: !!js process.env.DSH_OBSIDIAN_VAULT ?? process.cwd()\\n\\n# Fail-closed approval: the Obsidian mode never pops an \\\"escalate to\\n# danger-full-access?\\\" prompt, so an accidental click cannot widen the write\\n# boundary. If a user really needs one-off full access, they can set\\n# DSH_PERMISSION_MODE=danger-full-access explicitly and restart the service.\\n# NOTE: keep the folded-block `!!js >-` form — inline `? :` ternaries are\\n# mis-parsed by js-yaml into a mapping ({...: 'never'}).\\n- id: approval\\n  config:\\n    policy: !!js >-\\n      (process.env.DSH_PERMISSION_MODE ?? 'workspace-write') ===\\n      'danger-full-access' ? 'ask' : 'never'\\n\\n# The permission preset table must describe the composed default\\n# (workspace-write sandbox + never approval), otherwise boot fails with\\n# \\\"composed sandbox and approval defaults match no preset\\\".\\n- id: permission\\n  config:\\n    defaultPreset: obsidian-locked\\n    presets:\\n      read-only:\\n        sandbox: read-only\\n        approval: ask\\n      workspace-write:\\n        sandbox: workspace-write\\n        approval: ask\\n      obsidian-locked:\\n        sandbox: workspace-write\\n        approval: never\\n      danger-full-access:\\n        sandbox: danger-full-access\\n        approval: never\\n\",\"profile-pnpm-workspace.yaml\":\"packages:\\n  - .\\n\\nnodeLinker: hoisted\\nautoInstallPeers: false\\n\"}");
const EMBEDDED_TEMPLATES = JSON.parse("{\"AGENTS.md\":\"# DeepSeek 笔记助手 · 工作协议（AGENTS.md）\\n\\n> **适用范围与状态**：本协议面向**数学类知识**（数学、统计学等以概念-命题-证明-方法为主体的笔记与数学思维方式）设计，其他领域（代码、法律、医学、工程等）不要照搬。当前为**试做型 0.1.x**，未经长期使用测试，分层与提醒策略会演进；协议与实际需求冲突时，优先听用户的。\\n> **设计依据**：arXiv:2606.24775（四模块框架）+ arXiv:2607.05794（类型化记录层）+ arXiv:2604.03789（Rethlas 推理原语、生成-验证循环与定理检索工作流）。核心原则：**原文证据优先、写时保留、检索先粗后细、局部维护、证明可核查。**\\n\\n你是本 vault 的长期笔记助手。优先级：直接用户指令 > 本文件 > 记忆文件。\\n\\n## 0. 硬约束\\n\\n- 你只有文件读写/搜索工具和 ask_user 提问工具；所有读写限定在本 vault 内。\\n- 先读再答，禁止臆造；保留用户记号/术语/写作风格，修改用最小 diff。\\n- 用户是数学背景，笔记可能涉及数学、统计学、R 语言、LaTeX。\\n- **永不申请权限升级**：遇到 `[sandbox: file access denied ...]` 即视为禁止——停止重试，报告原因，不要使用 `sandbox_permissions`。需要写 vault 外的文件时，请用户自行处理。\\n\\n## 1. 会话开始\\n\\n系统提示已注入：画像、主题索引、记录索引、备忘录清单、事件时间线、最近问答线索。细节按第 5 节路由读文件，不要只凭注入摘要回答细节问题。\\n\\n## 2. 记忆结构（五层）与三写\\n\\n| 层（细→粗） | 文件 | 要点 |\\n|---|---|---|\\n| 证据层 | `memory/episodes/YYYY-MM-DD-*.md` | 每轮对话原始事件卡，append-only，模板见 `episodes/_README.md` |\\n| 记录层 | `memory/records/<slug>.md` | 类型化原子卡：fact/event/instruction/preference/**artifact**（例子、反例、分解计划、证明障碍等中间产物）；带 id、来源链接、变更历史；冲突用 superseded 而非删除，模板见 `records/_README.md` |\\n| 导航层 | `memory/topics/` | 主题索引与细节，只做路由 |\\n| 语义层 | `memory/profile.md` | 只放“现在仍成立”的稳定偏好/记号/授权，带修订历史 |\\n| 想法层 | `inbox/` | 待打磨想法，状态 inbox→polishing→done |\\n\\n另有一张**定理索引** `memory/theorems/index.md`（个人 Matlas）和一个**问题模板库** `memory/templates/`（题型/解法模板与定理的关联图，个人版 template-theorems graph；模板见各自 `_README.md`）。\\n\\n每轮收尾**按需三写**（细→粗；**本轮没有值得记忆的新信息就全部跳过**）：\\n\\n1. **episode**：只有出现新事实/决定/想法/修正时才向当天事件文件追加一节；闲聊、纯查询、无新信息不写。\\n2. **records**：把新事实/事件/指令/偏好/工作产物提炼为原子卡并调和：相同则更新原卡；冲突则旧卡 `superseded` + “变更历史”写“旧值 → 新值（日期）”；`source` 必须指向 episode；更新 `records/index.md`。\\n3. **topics/profile/theorems/templates**：只在确有变化时局部更新；禁止把整段对话总结进去——原文只在 episodes，原子事实只在 records。\\n\\n**执行纪律**：把同一轮的记忆写入合并成最少的工具调用，不要反复改；完成后只在回复末尾用一行说明（如“已记录：2 条”），不展示写入内容与过程。\\n\\n维护：agent 只维护索引与记录内容（`edit` 可增删行）；**旧 episode 的归档由 Obsidian 插件执行**（>90 天自动移入 `archive/`），不要自己移动/删除文件。冲突记录用 `superseded` 标记；profile 超过约 120 行时把收束条目改写为 episode/record 引用。\\n\\n## 3. 笔记工作流\\n\\n1. 理思路：先复述结构，给 2-3 个重组方案让用户选，不直接大改。\\n2. 补细节：补证明/例子/定义，标注 `<!-- AI 补全 -->`。\\n3. 审阅：按“逻辑错误 > 结构 > 记号表述 > 小瑕疵”分级，先讲最严重的，默认不直接改。\\n4. 找问题：检查假设是否明示、定义先于使用、记号一致性、例子与定理匹配、双链断裂。\\n5. 大改或删内容前用 ask_user 确认。\\n\\n## 4. 证明工作流（吸收 Rethlas 推理原语 + 生成-验证循环）\\n\\n处理“证明/猜想/构造/验证”类问题时，**根据当前状态动态选择**下列原语，不要固定顺序：\\n\\n1. **构造玩具例子**：卡住时构造满足假设与结论的简单实例，观察假设如何生效，找模式、不变量或证明策略。\\n2. **构造反例**：断言可疑时，测试“假设成立但结论失败”的情况；借助已知病态构造与障碍。\\n3. **检索相关结果（问题蒸馏优先）**：先把当前问题抽象成模板表达（去掉具体数字与语境），查 `memory/templates/index.md` 找同类题型/解法；命中则读模板卡与 `related_theorems`，对定理**去重聚合**后使用。再查 `memory/theorems/index.md` 与 grep 本 vault 笔记。对找到的定理：展开其定义、核对在当前假设下是否适用、显式说明术语在不同语境中的差异；**不只读定理陈述，还要读其证明，提取可迁移的技巧、归约与证明模式**。\\n4. **提出子目标分解计划**：在例子/反例/检索之后给出 2-3 个分解计划，每个计划列出关键障碍。\\n5. **直接证明**：逐个计划尝试证明子目标，记录失败的确切障碍。\\n6. **迭代分治**：所有计划失败时，按计划逐个深入局部修订（没有子代理，就自己分轮处理），保持连续性而非推倒重来。\\n7. **识别共同失败**：仍失败时，归纳共同障碍/无效分解/缺失背景，总结后进入下一轮计划。\\n\\n**生成-验证循环**：任何“候选证明”在输出前至少做一轮自查（角色切换为验证者）：\\n\\n- 逐句检查：跳过/“显然”的步骤是否可补；\\n- 检查关键错误与缺口；**未使用的假设**要么解释为何冗余，要么承认论证缺失；\\n- 核对每个引用：引用是否真实存在、版本与适用性、术语含义是否与当前证明一致；\\n- 结论：给证明标注置信度与未闭合点（`待补：…`），不要声称已证而没有核查。\\n\\n**工作产物沉淀**：构造的例子、反例、分解计划、障碍、提取到的证明模式，写为 records（type: artifact，见 `records/_README.md`）；重要定理/命题/引理/定义同步登记 `memory/theorems/index.md`；**遇到新的题型或解法时，从真实解题过程抽象一张模板卡**到 `memory/templates/`（见 `templates/_README.md`），并把用到的定理写入 `related_theorems`——这样模板库会从你实际做过的问题逐步生长。\\n\\n## 5. 检索路由\\n\\n| 查询类型 | 路由 |\\n|---|---|\\n| 精确事实 / 用户原话 / 日期数字 | grep `memory/episodes/` → 读命中文件 |\\n| 类型化原子事实 | 先看 `memory/records/index.md` → grep/读记录 → `source` 回原始证据 |\\n| 相关定理 / 命题 / 引理 | 先看 `memory/theorems/index.md` → grep 笔记全文 → 展开定义、核对适用性 |\\n| 同类题型 / 解法模式 | 先问题蒸馏 → 查 `memory/templates/index.md` → 读模板卡与关联定理（去重聚合） |\\n| 稳定偏好 / 记号 / 授权 | 读 `memory/profile.md` |\\n| 主题来龙去脉 | `topics/index.md` 定位 → 读 `topics/<slug>.md` 或相关笔记 |\\n| “当前最新状态” | 比较 frontmatter `updated` / 最新 episode 时间戳 |\\n| 跨会话分散证据 | grep episodes/records + index 时间线索汇聚 |\\n| 综合问题 | 先粗（index）后细（文件），按时间排好证据 |\\n\\n检索不到就明说“记忆里没有”，不要编造。\\n\\n## 6. 备忘录（捕获 → 关联 → 打磨）\\n\\n- **捕获**：识别到“一般性数学思路/方法/技巧/观点”时，回复末尾给 `💡 可捕捉的想法`，用 ask_user 征得同意（写入新 memo / 并入已有 / 稍后 / 忽略）。未经同意不新建；长期授权记入 profile。\\n- **关联检测**：写入前读 `inbox/index.md`。高度相关 → 并入已有 memo 的“关联观察”；中度相关 → 新建并互加 `related` 双链；独立 → 新建。memo 模板见 `inbox/_README.md`。\\n- **自动维护**：新证据追加到“关联观察”并更新 `updated`；状态流转 `inbox → polishing → done` 时更新 index；done 的升华内容写入正式笔记前仍需询问，memo 保留去向链接。\\n- **主动提醒**：本轮讨论与某 memo 明显相关，或插件标出陈旧候选（polishing > 3 天、inbox > 7 天、今天未提醒）时，回复末尾给 `🔔 备忘录提醒` 并 ask_user。每条每天最多一次，每轮最多 2 条；提醒后更新其 `last_reminded`。\\n- **打磨**：读 memo + related + episodes → 联想/检验/泛化 → 写“打磨记录”；成熟则建议归入正式笔记（写入前询问）。\\n\\n## 7. 目录约定\\n\\n```text\\nvault/\\n  AGENTS.md                          本协议（自动加载）\\n  .deepseek/\\n    memory/profile.md                语义层\\n    memory/topics/                   导航层（index + <topic>.md）\\n    memory/records/                  记录层（index + <slug>.md 原子卡）\\n    memory/theorems/                 定理索引（个人 Matlas：index + 登记模板）\\n    memory/templates/                问题模板库（题型/解法模板 ↔ 定理关联图）\\n    memory/episodes/                 证据层（index + 日期文件 + archive/）\\n    inbox/                           想法层（index + <slug>.md）\\n    cache/                           机器生成的对话索引（勿动）\\n```\\n\\n## 8. 回复与信息组织规范\\n\\n- **先结论**：第一段用 1-3 句给出直接回答（TL;DR），再展开理由。\\n- **分层组织**：多步骤内容用小节 + 编号列表；每个小节只讲一件事；先“做什么/结论”，再“为什么/细节”。\\n- **陌生概念最小解释**：首次出现的关键术语用括号一句话解释；一段需要 3 个以上陌生概念时，先给“最小背景”（≤3 条），细节另起一节，结尾问是否展开。\\n- **篇幅分级**：简单问题短答；复杂任务先给结构与最关键的 2-3 点。\\n- **中间过程静默**：记忆整理、检索等中间步骤只给结果（或末尾一行“已记录：N 条 / 已读取：[[文件]]”），不复述过程。\\n- 数学内容保留 LaTeX；引用笔记用 Obsidian 双链。\\n\",\"profile.md\":\"---\\ntype: memory/profile\\nupdated: 2026-08-15\\n---\\n\\n# 用户画像与稳定偏好\\n\\n> 本文件由 AI 维护：只放**现在仍然成立**的稳定事实（语义层）。过程性内容与原始对话证据放 `.deepseek/memory/episodes/`。更新原则：合并同类项；事实被推翻时用“~~旧值~~ → 新值（日期）”标注，不要删除历史。\\n\\n## 研究领域\\n\\n- （待填充：长期研究的数学分支/方向）\\n- （例如：实分析、概率论、……）\\n\\n## 当前关注\\n\\n- （待填充：近期在想的问题、在写的笔记；收束后下沉到 episodes 引用）\\n\\n## 理论偏好与方法偏好\\n\\n- （待填充：喜欢的框架、证明风格、构造性 vs 存在性、例子驱动的偏好……）\\n\\n## 记号与术语习惯\\n\\n- （待填充：用户常用记号、命名约定）\\n\\n## 工具与工作流\\n\\n- 笔记工具：Obsidian（vault: `D:\\\\Obsidian笔记数据库`）\\n- 数学排版：LaTeX\\n- （可补充：R / Stata / MATLAB 等）\\n\\n## 长期授权\\n\\n- （待填充：用户说“以后默认这样”的事项，例如：关键想法默认写入备忘录）\\n\\n## 修订历史\\n\\n- （AI 每次修改某条事实时在此加一行：`YYYY-MM-DD 事项：旧值 → 新值，证据见 episodes/YYYY-MM-DD-*`）\\n\",\"topics-index.md\":\"# 研究主题索引（导航层）\\n\\n> 本文件只做**路由**：每个主题一个 `##` 条目，按当前活跃度排序。细节超过 3 行就放 `topics/<slug>.md`，这里只留链接与一行概括。\\n\\n## 使用说明\\n\\n条目模板：\\n\\n```markdown\\n## <主题名>\\n\\n- 标签：#标签1 #标签2\\n- 状态：活跃 / 暂停 / 已收束\\n- 最新状态截至：YYYY-MM-DD\\n- 核心笔记：[[笔记名]]\\n- 一句话概括：……\\n- 详情：[[topics/<slug>]]（细节、开放问题、相关想法）\\n```\\n\\n（以下开始新增条目）\\n\",\"records-readme.md\":\"# 记忆记录层说明（原子记忆卡）\\n\\n> 本目录是**类型化原子记忆层**（借鉴 NapMem 的 typed memory records）：把每轮对话的证据提炼成一条条独立记录，位于原始事件（episodes）与主题/画像之间。\\n> 设计依据：arXiv:2607.05794（NapMem）——原始对话之上需要一层可检索、可验证、可溯源的原子记录。\\n\\n## 记录类型（五类）\\n\\n| type | 含义 | 例子 |\\n|---|---|---|\\n| `fact` | 客观事实 | “用户在读 Tao 的《实分析》第 3 章” |\\n| `event` | 发生过的事件/决定 | “2026-08-15 决定改用 3180 端口” |\\n| `instruction` | 用户的长期指令/约定 | “关键想法默认写入备忘录” |\\n| `preference` | 偏好/习惯/倾向 | “偏好构造性证明，先看例子” |\\n| `artifact` | 证明工作产物 | 玩具例子、反例、分解计划、证明障碍、提取到的证明模式（吸收 Rethlas 的工作记忆设计） |\\n\\n## 单条记录模板（`records/<slug>.md`）\\n\\n```markdown\\n---\\nid: rec-<slug>\\ntype: fact            # fact / event / instruction / preference / artifact\\nstatus: active        # active / superseded\\ncreated: YYYY-MM-DD\\nupdated: YYYY-MM-DD\\nsource: '[[YYYY-MM-DD-episode-slug]]'\\ntopic: <相关主题或“未归类”>\\nrelated: []\\n---\\n\\n# <一句话陈述>\\n\\n## 内容\\n<精确、可独立理解的事实/决定/指令/偏好>\\n\\n## 证据\\n- 来源事件：[[YYYY-MM-DD-episode-slug]]\\n- 原始表述摘录：<引用原文>\\n\\n## 变更历史\\n- YYYY-MM-DD：创建\\n```\\n\\n## 维护规则（AI 执行）\\n\\n1. **先写 episode，再写 record**：每轮收尾先追加原始事件卡，然后把本轮的新事实/决定/指令/偏好提炼为记录。\\n2. **调和（reconcile）而非追加**：新记录与已有记录相同 → 更新原记录、标注 `updated`；冲突 → 旧记录 `status: superseded` 并在“变更历史”写明“旧值 → 新值（日期）”，新记录指向旧记录；禁止删除旧记录。\\n3. **溯源**：每条记录的 `source` 必须指向至少一个 episode；无法溯源的内容不要写入记录层。\\n4. **传播**：记录更新后，再按需更新 `topics/index.md` 与 `profile.md`（局部更新）。\\n5. 更新 `records/index.md`（按类型分组一行一条）。\\n\",\"records-index.md\":\"# 记忆记录索引（按类型分组）\\n\\n> AI 维护：每条记录一行；状态变化时移动/更新。格式：`- [[rec-slug|一句话]] · topic · updated: YYYY-MM-DD`\\n\\n## fact（事实）\\n\\n（暂无）\\n\\n## event（事件）\\n\\n（暂无）\\n\\n## instruction（长期指令）\\n\\n（暂无）\\n\\n## preference（偏好）\\n\\n（暂无）\\n\\n## superseded（已更正）\\n\\n（暂无）\\n\",\"theorems-readme.md\":\"# 定理索引层说明（个人 Matlas）\\n\\n> 本目录是本 vault 的**个人定理检索层**（借鉴 Rethlas 的 Matlas 定理搜索引擎）：把笔记中已记录/已证明/未证明的定理、命题、引理、定义登记成可检索目录。\\n> 与远程数学数据库不同，这里只收录**你 vault 里已有的内容**，所以检索零成本、完全本地。\\n\\n## 登记条目模板（`theorems/index.md` 中一行）\\n\\n```markdown\\n- [[笔记名#定理名|定理名]] · 领域:实分析 · 关键词:紧算子, 谱 · 状态:已证/待证/引用\\n```\\n\\n## 登记规则（AI 执行）\\n\\n1. **什么时候登记**：在对话或笔记中出现新的重要定理/命题/引理/定义，或证明了一个新结果、标记了一个待证猜想时。\\n2. **状态**：\\n   - `已证`：本 vault 中有完整证明（或指向权威来源）；\\n   - `待证`：猜想/未闭合断言（在笔记中标注 `待补`）；\\n   - `引用`：从外部引用、尚未在 vault 内展开证明。\\n3. **检索纪律（吸收 Rethlas 的 Search relevant results）**：\\n   - 证明问题时先查本索引，再 grep 笔记全文；\\n   - 找到的定理要**展开定义、核对在当前假设下是否适用**，并显式说明术语在不同语境中的差异；\\n   - 不只读定理陈述，还要读其证明，提取可迁移的技巧、归约与证明模式；\\n   - 找不到就明说“本地索引没有”，不要编造出处。\\n\",\"theorems-index.md\":\"# 定理索引（个人 Matlas）\\n\\n> AI 维护：每行一条。格式：`- [[笔记名#定理名|定理名]] · 领域:<领域> · 关键词:<词1,词2> · 状态:已证/待证/引用`\\n\\n（尚无登记）\\n\",\"templates-readme.md\":\"# 问题模板层说明（模板-定理关联图，轻量版）\\n\\n> 本目录是本 vault 的**问题模板库**（借鉴 AAAI-26《Template-Theorems Graph Construction to Enhance Mathematical Reasoning Capabilities of LLM》）：把做过的题/证明模式抽象成可复用的“问题模板”，并与相关定理建立关联——模拟人类“见过同类题 → 想起相关定理”的认知过程。\\n> 与远程图数据库不同，这里是纯 markdown + 双链：每张模板卡就是一个节点，`related` 就是边。\\n\\n## 模板卡（`templates/<slug>.md`）\\n\\n```markdown\\n---\\ntitle: <模板名>\\ntype: problem          # problem（题型模板）/ solution（解题步骤模板）\\nupdated: YYYY-MM-DD\\nstatus: active         # active / superseded\\nrelated_theorems:\\n  - '[[theorems/index#定理名|定理名]]'\\nrelated_notes: []\\nsource: '[[YYYY-MM-DD-episode-slug]]'\\n---\\n\\n# <模板名>\\n\\n## 问题原型\\n<把具体题目抽象成一句话的一般形式，去掉表面细节>\\n\\n## 解题步骤\\n1. <关键步骤：每步是实质性推理，不是标点切分>\\n2. …\\n\\n## 适用边界\\n<什么条件下适用、常见误用>\\n\\n## 关联定理\\n- [[theorems/index#定理名|定理名]]：<在该模板中扮演的角色>\\n```\\n\\n## 维护规则（AI 执行）\\n\\n1. **问题蒸馏（检索前）**：遇到新问题时，先把它抽象成模板表达（去掉具体数字/语境），再查 `templates/index.md`。\\n2. **命中**：读命中的模板卡与 `related_theorems`，对定理**去重聚合**后进入推理；不要只取表面相似度最高的一个。\\n3. **未命中**：问题解决后，把新题型/新解法提取为模板卡（从你的实际解题过程中抽象），并把用到的定理写入 `related_theorems`——这就是“从种子问题逐步扩展知识库”。\\n4. **验证**：模板卡必须来源于真实解决过的问题或笔记（`source` 链接）；不得凭空编造定理名或引用不存在的笔记。\\n5. 更新 `templates/index.md`（每行一张卡）。\\n\",\"templates-index.md\":\"# 问题模板索引（模板-定理关联图）\\n\\n> AI 维护：每行一张模板卡。格式：`- [[templates/slug|模板名]] · type:problem/solution · 关联定理:定理1,定理2 · updated: YYYY-MM-DD`\\n\\n（尚无模板）\\n\",\"episodes-readme.md\":\"# 事件卡说明（证据层）\\n\\n> 本目录是记忆的**原始证据层**（append-only）。AI 每轮对话收尾前先在这里追加事件卡，再去更新 profile/topics。\\n>\\n> 设计依据：arXiv:2606.24775 的发现——保留原文/轻压缩优于抽象摘要（M1），写时保留优于早过滤（M2），时间戳多版本优于删除（M4）。\\n\\n## 文件与追加规则\\n\\n- 同一天的事件追加到当天文件 `YYYY-MM-DD-<slug>.md`；跨天开新文件。\\n- 同一文件内每个事件一个 `##` 小节，按时间顺序追加，**不重写已写内容**。\\n- 事实被推翻时：在新事件里写更正，旧小节保持原样。\\n\\n## 事件卡模板\\n\\n```markdown\\n## HH:MM <一句话标题>\\n\\n- 用户原话/关键表述：<保留原句，宁多勿删>\\n- 结论/产出：<本轮的实质结论，保留关键细节与数字>\\n- 事实修正：<旧事实 → 新事实；无则省略>\\n- 涉及：[[笔记名]] · 主题：<topic> · 想法：[[YYYY-MM-DD-idea-slug]]（如有）\\n```\\n\\n## 容量与归档\\n\\n- `index.md` 每行一条：`- [[YYYY-MM-DD-slug|标题]] — 主题A、主题B`。\\n- 目录超过约 40 个文件时，把最旧文件原样移入 `archive/`（不摘要、不合并），并更新 index 链接。\\n\",\"episodes-index.md\":\"# 事件时间索引\\n\\n> AI 维护：每天/每个新事件文件加一行；文件归档到 archive/ 后把链接改到 archive/。\\n> 格式：`- [[YYYY-MM-DD-slug|标题]] — 主题A、主题B`\\n\\n（尚无事件记录）\\n\",\"inbox-readme.md\":\"# 备忘录库 · inbox 说明\\n\\n> 本目录由 AI 自动维护：捕捉“一般性的数学思路、方法、技巧、观点”（新 memo 经你同意后创建），并跟踪每条想法的生命周期：\\n> `inbox`（待打磨）→ `polishing`（打磨中）→ `done`（已归入正式笔记）。\\n>\\n> - 每条想法一个 md 文件（`<slug>.md`），状态写在 frontmatter；\\n> - 总清单在 [`index.md`](index.md)，按状态分组；\\n> - AI 会在“出现新关联想法/证据”或“条目久未更新”时主动提醒你打磨。\\n\\n## 单条 memo 模板\\n\\n```markdown\\n---\\ntitle: <想法名>\\ntags: [想法/待打磨]\\nstatus: inbox            # inbox / polishing / done\\ncreated: YYYY-MM-DD\\nupdated: YYYY-MM-DD\\nlast_reminded: ''        # AI 每次提醒后写当天日期，用于每天最多提醒一次\\ntopic: <对应主题或“未归类”>\\nrelated: []              # 相关 memo/笔记双链：[[slug]]、[[笔记名]]\\n---\\n\\n# <想法名>\\n\\n## 想法\\n<一两句话的精确陈述>\\n\\n## 为什么值得捕捉\\n<可迁移性、与已有主题的关联>\\n\\n## 关联观察\\n<每次出现相关证据/想法就追加：日期、新证据、新角度、来源>\\n\\n## 待打磨\\n- [ ] <要澄清/证明/泛化的点>\\n\\n## 打磨记录\\n<打磨时追加：日期、本轮做了什么、下一步>\\n```\\n\\n## 维护规则（AI 执行）\\n\\n1. **不重复建卡**：新想法与已有 memo 高度相关时，并入其“关联观察”，而不是新建。\\n2. **双向关联**：相关 memo 之间互相在 `related` 加双链；打磨完成时在 `related` 加正式笔记链接。\\n3. **状态流转**：每次打磨后更新 `status` 与 `index.md` 分组。\\n4. **提醒记录**：每次主动提醒后更新 `last_reminded`；默认每条每天最多提醒一次。\\n5. **不删除历史**：done 的 memo 保留原文与打磨记录，作为想法的完整档案。\\n\",\"inbox-index.md\":\"# 备忘录索引（按状态分组）\\n\\n> AI 维护：新 memo 加入对应分组；状态变化时移动行。格式：`- [[slug|标题]] · 主题 · updated: YYYY-MM-DD`\\n\\n## inbox（待打磨）\\n\\n（暂无）\\n\\n## polishing（打磨中）\\n\\n（暂无）\\n\\n## done（已归入正式笔记）\\n\\n（暂无）\\n\"}");

const DEFAULT_SETTINGS = {
  port: 3180,
  dshInstallDir: '',
  dshHome: '',
  autoStart: true,
  autoInit: true,
  autoArchiveEpisodes: true,
  showRibbon: true,
  keepAliveOnUnload: false
};

// ── small helpers ───────────────────────────────────────────────────────────

function ensureFile(target, content, overwrite = false) {
  if (!overwrite && existsSync(target)) return false;
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, content, 'utf8');
  return true;
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Probe the local dsh web server with Node's http client. Do NOT use
 * browser `fetch` here: Obsidian's CSP can block renderer-side requests to
 * http://127.0.0.1, which previously made a healthy service look dead.
 */
function probeService(port, timeoutMs = 1500) {
  return new Promise((resolve) => {
    let settled = false;
    const finish = (value) => {
      if (settled) return;
      settled = true;
      resolve(value);
    };
    const request = http.get({ host: '127.0.0.1', port, path: '/', timeout: timeoutMs }, (response) => {
      response.resume();
      finish(response.statusCode >= 200 && response.statusCode < 500);
    });
    request.on('error', () => finish(false));
    request.on('timeout', () => {
      request.destroy();
      finish(false);
    });
  });
}

/**
 * The dsh server is a Node program. `process.execPath` inside Obsidian points
 * at the Electron binary (obsidian.exe), never at node, so we spawn `node`
 * from PATH. DSH_NODE_BIN allows an explicit override.
 */
function nodeExecutable() {
  const override = process.env.DSH_NODE_BIN?.trim();
  if (override) return override;
  return process.platform === 'win32' ? 'node.exe' : 'node';
}

// ── dsh detection ───────────────────────────────────────────────────────────

function validInstallDir(dir) {
  if (!dir) return null;
  const tryRoot = (root) => {
    try {
      const manifest = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'));
      if (manifest.name !== '@deepseek-ai/dsh') return null;
      return { installDir: root, script: join(root, 'lib', 'bin.js') };
    } catch {
      return null;
    }
  };
  // npm-global layout: <dir> itself is @deepseek-ai/dsh
  const direct = tryRoot(dir);
  if (direct) return direct;
  // custom layout: <dir>/dsh is the package (e.g. E:\software\deepseek-harness)
  const nested = tryRoot(join(dir, 'dsh'));
  if (nested) return nested;
  return null;
}

function parseLauncher(cmdPath) {
  try {
    const content = readFileSync(cmdPath, 'utf8');
    const dp0 = dirname(cmdPath);
    const match = /node\s+"([^"]+)"/i.exec(content);
    if (match) {
      let script = match[1].trim();
      if (script.startsWith('%~dp0')) script = join(dp0, script.slice('%~dp0'.length));
      if (script.toLowerCase().endsWith('bin.js') || /lib[\\/]bin\.js/i.test(script)) {
        return { installDir: dirname(dirname(script)), script };
      }
    }
    if (/dsh[\\/]lib[\\/]bin\.js/.test(content)) {
      return { installDir: dp0, script: join(dp0, 'dsh', 'lib', 'bin.js') };
    }
    return { installDir: dp0, script: '' };
  } catch {
    return null;
  }
}

function detectInstallCandidates(settings) {
  const candidates = [];
  if (settings.dshInstallDir) candidates.push(settings.dshInstallDir);
  if (process.env.DSH_HOME) candidates.push(dirname(process.env.DSH_HOME));
  const appData = process.env.APPDATA || join(homedir(), 'AppData', 'Roaming');
  candidates.push(join(appData, 'npm', 'node_modules', '@deepseek-ai', 'dsh'));
  return candidates;
}

function detectFromShell() {
  const result = [];
  let command;
  if (process.platform === 'win32') {
    command = spawnSync('where', ['dsh'], { encoding: 'utf8', timeout: 6000, windowsHide: true });
  } else {
    command = spawnSync('which', ['dsh'], { encoding: 'utf8', timeout: 6000 });
  }
  if (command.status !== 0 || !command.stdout) return result;
  for (const raw of command.stdout.split(/\r?\n/)) {
    const line = raw.trim();
    if (line === '') continue;
    const parsed = parseLauncher(line);
    if (parsed) result.push(parsed);
    result.push({ installDir: dirname(line), script: '' });
  }
  return result;
}

function detectDsh(settings) {
  for (const dir of detectInstallCandidates(settings)) {
    const valid = validInstallDir(dir);
    if (valid) return valid;
  }
  for (const parsed of detectFromShell()) {
    const valid = validInstallDir(parsed.installDir);
    if (valid) return valid;
    if (parsed.script) return { installDir: parsed.installDir, script: parsed.script };
  }
  return null;
}

function detectDshHome(settings, detected) {
  if (settings.dshHome) return settings.dshHome;
  if (process.env.DSH_HOME) return process.env.DSH_HOME;
  if (detected?.installDir && existsSync(join(detected.installDir, '.dsh'))) {
    return join(detected.installDir, '.dsh');
  }
  return join(homedir(), '.dsh');
}

// ── dsh service manager ─────────────────────────────────────────────────────

class DshService {
  constructor(plugin) {
    this.plugin = plugin;
    this.child = null;
    this.status = 'unknown';
    this.logLines = [];
    this.listeners = new Set();
    this.cachedLocation = undefined;
  }

  onChange(listener) {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  setStatus(status) {
    if (this.status === status) return;
    this.status = status;
    for (const listener of this.listeners) listener(status);
  }

  appendLog(text) {
    for (const line of String(text).split(/\r?\n/)) {
      if (line.trim() === '') continue;
      this.logLines.push(line);
      if (this.logLines.length > 600) this.logLines.shift();
    }
  }

  location(force = false) {
    if (!force && this.cachedLocation !== undefined) return this.cachedLocation;
    const detected = detectDsh(this.plugin.settings);
    this.cachedLocation = detected === null ? null : {
      installDir: detected.installDir,
      script: detected.script,
      home: detectDshHome(this.plugin.settings, detected)
    };
    return this.cachedLocation;
  }

  async ensureStarted() {
    if (await probeService(this.plugin.settings.port, 1200)) {
      this.setStatus('running');
      return;
    }
    return this.start();
  }

  async start() {
    if (this.child !== null && this.child.exitCode === null) return;
    if (await probeService(this.plugin.settings.port, 1200)) {
      this.setStatus('running');
      return;
    }
    const location = this.location();
    if (location === null) {
      this.setStatus('missing-dsh');
      throw new Error('未找到 dsh。请打开插件设置，点击“自动检测”，或先安装 DeepSeek Harness。');
    }
    const vaultPath = this.plugin.app.vault.adapter.getBasePath();
    const env = {
      ...process.env,
      DSH_HOME: location.home,
      DSH_OBSIDIAN_VAULT: vaultPath,
      DSH_SESSIONS_ROOT: join(location.home, 'sessions')
    };
    const args = location.script
      ? [location.script, '--profile', PRESET_NAME, '--port', String(this.plugin.settings.port)]
      : ['--profile', PRESET_NAME, '--port', String(this.plugin.settings.port)];
    const executable = location.script ? nodeExecutable() : 'dsh';
    // Without a resolved script we rely on the dsh launcher; Windows needs a
    // shell to execute .cmd shims.
    const shell = !location.script && process.platform === 'win32';
    this.setStatus('starting');
    this.appendLog(`启动：${executable} ${args.join(' ')}`);
    const child = spawn(executable, args, { env, windowsHide: true, shell, stdio: ['ignore', 'pipe', 'pipe'] });
    this.child = child;
    let spawnError = null;
    child.stdout.on('data', (chunk) => this.appendLog(chunk));
    child.stderr.on('data', (chunk) => this.appendLog(chunk));
    // Without this handler a missing `node` binary throws an uncaught
    // ChildProcess 'error' event and can take the whole plugin down.
    child.on('error', (error) => {
      spawnError = error;
      this.appendLog(`启动失败：${String(error)}`);
      if (this.child === child) this.child = null;
      this.setStatus('error');
    });
    child.on('exit', (code) => {
      this.appendLog(`dsh 已退出，退出码 ${code}`);
      if (this.child === child) this.child = null;
      if (this.status !== 'stopping' && spawnError === null) this.setStatus(code === 0 ? 'stopped' : 'error');
    });
    for (let attempt = 0; attempt < 60; attempt += 1) {
      await sleep(750);
      if (await probeService(this.plugin.settings.port, 1000)) {
        this.setStatus('running');
        return;
      }
      if (this.child === null || this.child.exitCode !== null) break;
    }
    this.setStatus('error');
    throw new Error(`dsh 服务未能在端口 ${this.plugin.settings.port} 上启动。${this.logLines.slice(-3).join(' | ')}`);
  }

  async stop() {
    this.setStatus('stopping');
    const child = this.child;
    this.child = null;
    if (child !== null && child.exitCode === null) {
      const exited = new Promise((resolve) => {
        child.once('exit', resolve);
        setTimeout(resolve, 1500);
      });
      child.kill();
      await exited;
    }
    this.setStatus('stopped');
  }

  async restart() {
    await this.stop();
    await sleep(500);
    return this.start();
  }
}

// ── embedded configuration bootstrap ────────────────────────────────────────

function bootstrapDshConfig(plugin, force = false) {
  const location = plugin.service.location();
  if (location === null) throw new Error('未检测到 dsh。请先在设置中配置 dsh 安装目录。');
  const home = location.home;
  const presetRoot = join(home, '.agent-presets', PRESET_NAME);
  const profileRoot = join(home, 'profiles', PRESET_NAME);
  const written = [];

  // Code always refreshes; user-editable files are preserved unless forced.
  if (ensureFile(join(presetRoot, 'obsidian-memory.mjs'), EMBEDDED_PRESET['obsidian-memory.mjs'], true)) written.push('preset/obsidian-memory.mjs');
  if (ensureFile(join(presetRoot, 'preset.yml'), EMBEDDED_PRESET['preset.yml'], force)) written.push('preset/preset.yml');
  if (ensureFile(join(presetRoot, 'agent.cordis.yml'), EMBEDDED_PRESET['agent.cordis.yml'], force)) written.push('preset/agent.cordis.yml');
  if (ensureFile(join(profileRoot, 'package.json'), EMBEDDED_PRESET['profile-package.json'], force)) written.push('profile/package.json');
  if (ensureFile(join(profileRoot, 'cordis.yml'), EMBEDDED_PRESET['profile-cordis.yml'], true)) written.push('profile/cordis.yml');
  if (ensureFile(join(profileRoot, 'cordis.patch.yml'), EMBEDDED_PRESET['profile-cordis.patch.yml'], force)) written.push('profile/cordis.patch.yml');
  if (ensureFile(join(profileRoot, 'pnpm-workspace.yaml'), EMBEDDED_PRESET['profile-pnpm-workspace.yaml'], force)) written.push('profile/pnpm-workspace.yaml');
  return { home, written };
}

function bootstrapVaultTemplates(plugin, force = false) {
  const vault = plugin.app.vault.adapter.getBasePath();
  const mapping = [
    ['AGENTS.md', join(vault, 'AGENTS.md')],
    ['profile.md', join(vault, '.deepseek', 'memory', 'profile.md')],
    ['topics-index.md', join(vault, '.deepseek', 'memory', 'topics', 'index.md')],
    ['records-readme.md', join(vault, '.deepseek', 'memory', 'records', '_README.md')],
    ['records-index.md', join(vault, '.deepseek', 'memory', 'records', 'index.md')],
    ['theorems-readme.md', join(vault, '.deepseek', 'memory', 'theorems', '_README.md')],
    ['theorems-index.md', join(vault, '.deepseek', 'memory', 'theorems', 'index.md')],
    ['templates-readme.md', join(vault, '.deepseek', 'memory', 'templates', '_README.md')],
    ['templates-index.md', join(vault, '.deepseek', 'memory', 'templates', 'index.md')],
    ['episodes-readme.md', join(vault, '.deepseek', 'memory', 'episodes', '_README.md')],
    ['episodes-index.md', join(vault, '.deepseek', 'memory', 'episodes', 'index.md')],
    ['inbox-readme.md', join(vault, '.deepseek', 'inbox', '_README.md')],
    ['inbox-index.md', join(vault, '.deepseek', 'inbox', 'index.md')]
  ];
  const written = [];
  for (const [key, target] of mapping) {
    if (ensureFile(target, EMBEDDED_TEMPLATES[key], force)) written.push(target);
  }
  return { vault, written };
}

/**
 * Host-side memory maintenance: move episode files older than `maxDays` into
 * `episodes/archive/` and update the episode index links. The agent has no
 * delete/move tools, so the Obsidian plugin owns this one lifecycle operation.
 */
function archiveOldEpisodes(plugin, maxDays = 90) {
  const vault = plugin.app.vault.adapter.getBasePath();
  const episodesDir = join(vault, '.deepseek', 'memory', 'episodes');
  if (!existsSync(episodesDir)) return { moved: 0 };
  const archiveDir = join(episodesDir, 'archive');
  const cutoff = Date.now() - maxDays * 86400000;
  const moved = [];
  let entries;
  try {
    entries = readdirSync(episodesDir, { withFileTypes: true });
  } catch {
    return { moved: 0 };
  }
  for (const entry of entries) {
    if (!entry.isFile() || !entry.name.endsWith('.md') || entry.name === 'index.md' || entry.name.startsWith('_')) continue;
    const source = join(episodesDir, entry.name);
    let stats;
    try {
      stats = statSync(source);
    } catch {
      continue;
    }
    if (stats.mtimeMs >= cutoff) continue;
    try {
      mkdirSync(archiveDir, { recursive: true });
      let target = join(archiveDir, entry.name);
      let suffix = 1;
      while (existsSync(target)) {
        suffix += 1;
        target = join(archiveDir, entry.name.replace(/\.md$/, `-${suffix}.md`));
      }
      renameSync(source, target);
      moved.push({ name: entry.name, target: join('archive', entry.name.replace(/\.md$/, suffix === 1 ? '.md' : `-${suffix}.md`)) });
    } catch {
      // Leave the file in place on any maintenance failure.
    }
  }
  if (moved.length > 0) {
    const indexPath = join(episodesDir, 'index.md');
    if (existsSync(indexPath)) {
      try {
        let indexText = readFileSync(indexPath, 'utf8');
        for (const item of moved) {
          indexText = indexText.replaceAll(`[[${item.name.replace(/\.md$/, '')}|`, `[[${item.target.replace(/\.md$/, '')}|`);
          indexText = indexText.replaceAll(`[[${item.name.replace(/\.md$/, '')}]]`, `[[${item.target.replace(/\.md$/, '')}]]`);
        }
        writeFileSync(indexPath, indexText, 'utf8');
      } catch {
        // Index update is best-effort; moved files are already safe.
      }
    }
  }
  return { moved: moved.length };
}

// ── sidebar view ────────────────────────────────────────────────────────────

class DshMathView extends ItemView {
  constructor(leaf, plugin) {
    super(leaf);
    this.plugin = plugin;
    this.offStatus = null;
    this.iframe = null;
  }

  getViewType() {
    return VIEW_TYPE;
  }

  getDisplayText() {
    return 'DSH数学笔记助手';
  }

  getIcon() {
    return 'message-square';
  }

  async onOpen() {
    this.contentEl.empty();
    this.contentEl.addClass('dsh-obsidian-math-view');
    this.statusRow = this.contentEl.createDiv({ cls: 'dsh-obsidian-math-status' });
    this.body = this.contentEl.createDiv({ cls: 'dsh-obsidian-math-body' });
    this.offStatus = this.plugin.service.onChange((status) => this.render(status));
    const status = await this.plugin.service.ensureStarted().then(() => this.plugin.service.status).catch(() => this.plugin.service.status);
    this.render(status);
  }

  render(status) {
    if (this.statusRow === undefined) return;
    if (status === 'running') {
      this.statusRow.empty();
      this.statusRow.style.display = 'none';
      const expectedSrc = `http://127.0.0.1:${this.plugin.settings.port}/`;
      if (this.iframe === null) {
        this.iframe = this.body.createEl('iframe', {
          cls: 'dsh-obsidian-math-iframe',
          attr: { src: expectedSrc }
        });
      } else if (this.iframe.getAttribute('src') !== expectedSrc) {
        this.iframe.setAttribute('src', expectedSrc);
      }
      return;
    }
    this.statusRow.style.display = '';
    if (this.iframe !== null) {
      this.iframe.remove();
      this.iframe = null;
    }
    this.statusRow.empty();
    const message = {
      starting: '正在启动 DeepSeek Harness 服务…',
      'missing-dsh': '未找到 dsh（DeepSeek Harness）。请打开插件设置并检测 dsh 安装路径。',
      error: 'dsh 服务启动失败。请打开插件设置查看日志。',
      stopped: 'dsh 服务已停止。',
      stopping: '正在停止服务…',
      unknown: '服务状态未知。'
    }[status] ?? '服务状态未知。';
    this.statusRow.setText(message);
    const actions = this.statusRow.createDiv({ cls: 'dsh-obsidian-math-actions' });
    const retry = actions.createEl('button', { text: '重试' });
    retry.addEventListener('click', async () => {
      this.render('starting');
      await this.plugin.service.ensureStarted().catch((error) => new Notice(String(error)));
      this.render(this.plugin.service.status);
    });
    const settings = actions.createEl('button', { text: '打开设置' });
    settings.addEventListener('click', () => this.plugin.openSettings());
  }

  async onClose() {
    if (this.offStatus !== null) this.offStatus();
  }
}

// ── plugin ──────────────────────────────────────────────────────────────────

class DshObsidianMathPlugin extends Plugin {
  async onload() {
    await this.loadSettings();
    this.service = new DshService(this);
    this.registerView(VIEW_TYPE, (leaf) => new DshMathView(leaf, this));
    if (this.settings.showRibbon) {
      this.addRibbonIcon('message-square', '打开 DSH数学笔记助手', () => this.activateView());
    }
    this.addCommand({
      id: 'open-dsh-math-assistant',
      name: '打开 DSH数学笔记助手',
      callback: () => this.activateView()
    });
    this.addCommand({
      id: 'start-dsh-service',
      name: '启动 DSH 服务',
      callback: async () => {
        try {
          await this.service.start();
          new Notice('DSH 服务已运行');
        } catch (error) {
          new Notice(String(error));
        }
      }
    });
    this.addCommand({
      id: 'stop-dsh-service',
      name: '停止 DSH 服务',
      callback: async () => {
        await this.service.stop();
        new Notice('DSH 服务已停止');
      }
    });
    this.addSettingTab(new DshObsidianSettingTab(this.app, this));
    if (this.settings.autoInit) {
      this.app.workspace.onLayoutReady(() => {
        try {
          bootstrapDshConfig(this, false);
          bootstrapVaultTemplates(this, false);
        } catch (error) {
          new Notice(`dsh-obsidian-math: ${String(error)}`);
        }
      });
    }
    if (this.settings.autoArchiveEpisodes) {
      this.app.workspace.onLayoutReady(() => {
        try {
          const result = archiveOldEpisodes(this, 90);
          if (result.moved > 0) new Notice(`记忆维护：已归档 ${result.moved} 个旧事件文件`);
        } catch (error) {
          new Notice(`记忆维护失败：${String(error)}`);
        }
      });
    }
    if (this.settings.autoStart) {
      this.app.workspace.onLayoutReady(() => {
        setTimeout(() => {
          this.service.ensureStarted().catch(() => {});
        }, 1200);
      });
    }
  }

  async activateView() {
    const { workspace } = this.app;
    let leaf = workspace.getLeavesOfType(VIEW_TYPE)[0];
    if (!leaf) {
      if (typeof workspace.getRightLeaf === 'function') {
        leaf = workspace.getRightLeaf(false);
      } else {
        leaf = workspace.getLeaf('tab');
      }
      await leaf.setViewState({ type: VIEW_TYPE, active: true });
    }
    if (typeof workspace.revealLeaf === 'function') await workspace.revealLeaf(leaf);
    else workspace.setActiveLeaf(leaf);
  }

  openSettings() {
    const setting = this.app.setting;
    if (!setting) return;
    try {
      setting.open();
    } catch {
      // ignored; openTabById below is the important part
    }
    try {
      setting.openTabById('dsh-obsidian-math');
    } catch {
      // older Obsidian: the settings root is already open
    }
  }

  async loadSettings() {
    this.settings = Object.assign({}, DEFAULT_SETTINGS, await this.loadData());
  }

  async saveSettings() {
    await this.saveData(this.settings);
  }

  onunload() {
    if (this.service?.child !== null && !this.settings.keepAliveOnUnload) {
      this.service?.stop();
    }
  }
}

module.exports = DshObsidianMathPlugin;

// ── settings tab ────────────────────────────────────────────────────────────

class DshObsidianSettingTab extends PluginSettingTab {
  constructor(app, plugin) {
    super(app, plugin);
    this.plugin = plugin;
  }

  display() {
    const { containerEl } = this;
    containerEl.empty();
    containerEl.createEl('h2', { text: 'DSH数学笔记助手' });
    containerEl.createEl('p', { text: `版本 ${this.plugin.manifest?.version ?? ''}` });
    containerEl.createEl('p', { text: '在 Obsidian 右侧栏嵌入 DeepSeek Harness 数学记忆助手。插件会自动启动 dsh 服务，无需额外打开命令行窗口。' });
    containerEl.createEl('p', { cls: 'dsh-obsidian-math-security-note', text: '🔒 安全模式：助手只能写当前 vault 内的文件；权限升级审批默认关闭，不会弹出“是否提权”的窗口；工具集中没有删除类工具。' });
    containerEl.createEl('p', { cls: 'dsh-obsidian-math-security-note', text: '🧭 适用范围：面向数学类知识（数学、统计学笔记与数学思维方式）设计，其他领域的知识可能需要不同的记忆架构。当前为试做型（0.1.x），记忆架构尚未经过长期使用测试，后续会继续演进。' });

    new Setting(containerEl)
      .setName('端口')
      .setDesc('dsh 网页服务的本地端口。默认 3180，与默认 dsh web 的 3080 互不冲突。')
      .addText((text) => text
        .setPlaceholder('3180')
        .setValue(String(this.plugin.settings.port))
        .onChange(async (value) => {
          const port = Number.parseInt(value, 10);
          if (Number.isInteger(port) && port > 0 && port < 65536) {
            this.plugin.settings.port = port;
            await this.plugin.saveSettings();
          }
        }));

    const location = this.plugin.service.location();
    new Setting(containerEl)
      .setName('dsh 安装目录')
      .setDesc(location ? `已检测到：${location.installDir}` : '尚未检测到。可点击“自动检测”，或手动填写目录后回车。')
      .addText((text) => text
        .setPlaceholder('留空则自动检测')
        .setValue(this.plugin.settings.dshInstallDir)
        .onChange(async (value) => {
          this.plugin.settings.dshInstallDir = value.trim();
          this.plugin.service.cachedLocation = undefined;
          await this.plugin.saveSettings();
        }))
      .addButton((button) => button.setButtonText('自动检测').onClick(async () => {
        const found = this.plugin.service.location(true);
        if (found === null) {
          new Notice('未找到 dsh。请先安装 DeepSeek Harness，或手动填写安装目录。');
        } else {
          this.plugin.settings.dshInstallDir = found.installDir;
          await this.plugin.saveSettings();
          new Notice(`已检测到 dsh：${found.installDir}`);
          this.display();
        }
      }));

    new Setting(containerEl)
      .setName('DSH_HOME')
      .setDesc(location ? `已自动探测：${location.home}（可直接修改）` : 'dsh 主目录（preset、profile、会话日志所在处）。留空则自动探测。')
      .addText((text) => text
        .setPlaceholder('留空则自动探测')
        .setValue(location?.home ?? this.plugin.settings.dshHome)
        .onChange(async (value) => {
          this.plugin.settings.dshHome = value.trim();
          this.plugin.service.cachedLocation = undefined;
          await this.plugin.saveSettings();
        }));

    new Setting(containerEl)
      .setName('启动 Obsidian 时自动启动服务')
      .setDesc('打开 Obsidian 后自动拉起 dsh 服务，无需手动操作。')
      .addToggle((toggle) => toggle.setValue(this.plugin.settings.autoStart).onChange(async (value) => {
        this.plugin.settings.autoStart = value;
        await this.plugin.saveSettings();
      }));

    new Setting(containerEl)
      .setName('自动初始化 dsh 配置与记忆模板')
      .setDesc('首次运行时自动补齐 preset、profile 与 vault 内的记忆模板（只补缺失文件，不覆盖已有修改）。')
      .addToggle((toggle) => toggle.setValue(this.plugin.settings.autoInit).onChange(async (value) => {
        this.plugin.settings.autoInit = value;
        await this.plugin.saveSettings();
      }));

    new Setting(containerEl)
      .setName('启动时自动归档旧事件（超过 90 天）')
      .setDesc('把过旧的事件卡移入 episodes/archive/ 并更新索引——由插件执行，agent 本身没有删除/移动工具。')
      .addToggle((toggle) => toggle.setValue(this.plugin.settings.autoArchiveEpisodes).onChange(async (value) => {
        this.plugin.settings.autoArchiveEpisodes = value;
        await this.plugin.saveSettings();
      }));

    new Setting(containerEl)
      .setName('显示侧边栏按钮')
      .setDesc('在 Obsidian 左侧 ribbon 显示一键打开按钮。')
      .addToggle((toggle) => toggle.setValue(this.plugin.settings.showRibbon).onChange(async (value) => {
        this.plugin.settings.showRibbon = value;
        await this.plugin.saveSettings();
      }));

    new Setting(containerEl)
      .setName('关闭 Obsidian 时保留服务')
      .setDesc('默认关闭：插件退出时会停止它自己启动的 dsh 服务。')
      .addToggle((toggle) => toggle.setValue(this.plugin.settings.keepAliveOnUnload).onChange(async (value) => {
        this.plugin.settings.keepAliveOnUnload = value;
        await this.plugin.saveSettings();
      }));

    containerEl.createEl('h3', { text: '配置' });
    const configRow = containerEl.createDiv({ cls: 'dsh-obsidian-math-config-actions' });
    const initButton = configRow.createEl('button', { text: '初始化 dsh 配置与 vault 模板' });
    initButton.addEventListener('click', async () => {
      try {
        const dsh = bootstrapDshConfig(this.plugin, false);
        const vault = bootstrapVaultTemplates(this.plugin, false);
        new Notice(`dsh 配置已就绪（${dsh.written.length} 个文件）。vault 模板：${vault.written.length} 个。`);
        this.display();
      } catch (error) {
        new Notice(String(error));
      }
    });
    const forceButton = configRow.createEl('button', { text: '强制重装 dsh 配置' });
    forceButton.addEventListener('click', async () => {
      try {
        const result = bootstrapDshConfig(this.plugin, true);
        new Notice(`dsh 配置已重装到 ${result.home}`);
        this.display();
      } catch (error) {
        new Notice(String(error));
      }
    });
    const archiveButton = configRow.createEl('button', { text: '立即归档旧事件（>90 天）' });
    archiveButton.addEventListener('click', () => {
      try {
        const result = archiveOldEpisodes(this.plugin, 90);
        new Notice(result.moved > 0 ? `已归档 ${result.moved} 个旧事件文件` : '没有需要归档的旧事件');
        this.display();
      } catch (error) {
        new Notice(String(error));
      }
    });

    containerEl.createEl('h3', { text: '服务' });
    const serviceRow = containerEl.createDiv({ cls: 'dsh-obsidian-math-config-actions' });
    const startButton = serviceRow.createEl('button', { text: '启动服务' });
    startButton.addEventListener('click', async () => {
      await this.plugin.service.start().catch((error) => new Notice(String(error)));
      this.display();
    });
    const stopButton = serviceRow.createEl('button', { text: '停止服务' });
    stopButton.addEventListener('click', async () => {
      await this.plugin.service.stop();
      this.display();
    });
    const restartButton = serviceRow.createEl('button', { text: '重启服务' });
    restartButton.addEventListener('click', async () => {
      await this.plugin.service.restart().catch((error) => new Notice(String(error)));
      this.display();
    });
    const statusLabels = {
      running: '运行中',
      starting: '启动中',
      stopped: '已停止',
      stopping: '停止中',
      'missing-dsh': '未找到 dsh',
      error: '错误',
      unknown: '未知'
    };
    serviceRow.createEl('span', { text: ` 状态：${statusLabels[this.plugin.service.status] ?? this.plugin.service.status}` });

    const log = this.plugin.service.logLines.join('\n');
    if (log !== '') {
      containerEl.createEl('h3', { text: `最近服务日志（共 ${this.plugin.service.logLines.length} 行，可滚动）` });
      const copyLog = containerEl.createEl('button', { text: '复制全部日志' });
      copyLog.addEventListener('click', async () => {
        try {
          await navigator.clipboard.writeText(log);
          new Notice('日志已复制到剪贴板');
        } catch {
          new Notice('复制失败，请手动选择日志文本');
        }
      });
      containerEl.createEl('pre', { text: log, cls: 'dsh-obsidian-math-log' });
    }
  }
}
